// ===================================================
// CONFIG CLIENTE — TEMPLATE GENÉRICO PARA VENDA
// ===================================================
const config = {
  empresa: {
    nome: "NOME_DO_CLIENTE",
    cidade: "CIDADE_DO_CLIENTE",
    telefone_responsavel: "55DDDNUMERO",
    waha_base_url: "http://IP_DA_VPS:3000",
    waha_api_key: "SUA_WAHA_API_KEY",
    session: "default"
  },

  supabase: {
    url: "https://SEU_PROJECT_REF.supabase.co",
    service_role_key: "SUA_SUPABASE_SERVICE_ROLE_KEY"
  },

  lembrete: {
    timezone: "America/Campo_Grande",

    // 1 hora antes:
    // envia lembrete ao cliente + responsável.
    lembrete_1h_antes_minutos: 60,

    // 30 minutos antes:
    // envia alerta interno só para o responsável.
    lembrete_30min_dono_minutos: 30
  }
};

return [{ json: { config, started_at: new Date().toISOString() } }];

function brDateTimeToDate(dateBr, time) {
  if (!dateBr || !time) return null;

  const parts = String(dateBr).split("/");
  if (parts.length !== 3) return null;

  const [dd, mm, yyyy] = parts;
  const [hh, min] = String(time).split(":");

  if (!dd || !mm || !yyyy || !hh) return null;

  return new Date(
    Number(yyyy),
    Number(mm) - 1,
    Number(dd),
    Number(hh),
    Number(min || 0),
    0
  );
}

const previous = $item(0).$node["01 - CONFIG CLIENTE"].json;
const config = previous.config;
const agendamentos = Array.isArray($json) ? $json : [];
const now = new Date();

const eventos = [];

for (const ag of agendamentos) {
  const dataConfirmada = ag.data_confirmada || ag.data_desejada || "";
  const horaConfirmada = ag.hora_confirmada || ag.hora_desejada || "";

  const agDate = brDateTimeToDate(dataConfirmada, horaConfirmada);
  if (!agDate) continue;

  const diffMin = (agDate.getTime() - now.getTime()) / 60000;

  // Janela 1h antes: manda cliente + responsável
  if (
    diffMin <= config.lembrete.lembrete_1h_antes_minutos &&
    diffMin > config.lembrete.lembrete_30min_dono_minutos
  ) {
    if (ag.lembrete_1h_cliente_enviado !== true) {
      eventos.push({
        tipo: "CLIENTE_1H",
        agendamento: {
          ...ag,
          data_confirmada: dataConfirmada,
          hora_confirmada: horaConfirmada,
          minutos_para_agendamento: Math.round(diffMin)
        }
      });
    }

    if (ag.lembrete_1h_responsavel_enviado !== true) {
      eventos.push({
        tipo: "RESPONSAVEL_1H",
        agendamento: {
          ...ag,
          data_confirmada: dataConfirmada,
          hora_confirmada: horaConfirmada,
          minutos_para_agendamento: Math.round(diffMin)
        }
      });
    }
  }

  // Janela 30min antes: manda só responsável
  if (
    diffMin <= config.lembrete.lembrete_30min_dono_minutos &&
    diffMin > 0 &&
    ag.lembrete_30min_responsavel_enviado !== true
  ) {
    eventos.push({
      tipo: "RESPONSAVEL_30MIN",
      agendamento: {
        ...ag,
        data_confirmada: dataConfirmada,
        hora_confirmada: horaConfirmada,
        minutos_para_agendamento: Math.round(diffMin)
      }
    });
  }
}

return [{
  json: {
    ...previous,
    agendamentos_total: agendamentos.length,
    eventos,
    total_eventos_para_enviar: eventos.length
  }
}];

const config = $json.config;
const outputs = [];

for (const evento of $json.eventos || []) {
  const ag = evento.agendamento;
  let chatId = "";
  let text = "";

  if (evento.tipo === "CLIENTE_1H") {
    chatId = ag.cliente_telefone;

    const nome = ag.cliente_nome || "tudo bem";
    text = `Olá, ${nome}! 🚗✨

Passando para lembrar do seu agendamento na ${config.empresa.nome}.

Serviço: ${ag.servico_nome}
Veículo: ${ag.veiculo}
Horário: ${ag.data_confirmada} às ${ag.hora_confirmada}
Tempo estimado: ${ag.tempo_texto || "não informado"}
Valor: ${ag.preco_texto || "não informado"}

Te esperamos!`;
  }

  if (evento.tipo === "RESPONSAVEL_1H") {
    chatId = config.empresa.telefone_responsavel;

    text = `📅 Próximo atendimento - ${config.empresa.nome}

Cliente: ${ag.cliente_nome || "Não informado"}
WhatsApp: https://wa.me/${ag.cliente_telefone}
Serviço: ${ag.servico_nome}
Veículo: ${ag.veiculo}
Horário: ${ag.data_confirmada} às ${ag.hora_confirmada}

💡 Prepare a equipe para o atendimento.`;
  }

  if (evento.tipo === "RESPONSAVEL_30MIN") {
    chatId = config.empresa.telefone_responsavel;

    text = `⚠️ Cliente chegando em breve - ${config.empresa.nome}

Faltam aproximadamente ${ag.minutos_para_agendamento} minutos.

Cliente: ${ag.cliente_nome || "Não informado"}
WhatsApp: https://wa.me/${ag.cliente_telefone}
Serviço: ${ag.servico_nome}
Veículo: ${ag.veiculo}
Horário: ${ag.data_confirmada} às ${ag.hora_confirmada}

🚗 Deixe tudo pronto para receber o cliente.`;
  }

  if (!chatId || !text) continue;

  outputs.push({
    json: {
      config,
      evento_tipo: evento.tipo,
      agendamento_id: ag.id,
      chatId,
      text
    }
  });
}

return outputs;

const config = $json.config;

return [{
  json: {
    ...$json,
    action: "send",
    waha_base_url: config.empresa.waha_base_url,
    waha_api_key: config.empresa.waha_api_key,
    session: config.empresa.session,
    chatId: $json.chatId,
    text: $json.text
  }
}];

const previous = $item(0).$node["06 - Preparar Envio WAHA"].json;

const body = {
  updated_at: new Date().toISOString()
};

if (previous.evento_tipo === "CLIENTE_1H") {
  body.lembrete_1h_cliente_enviado = true;
  body.lembrete_1h_cliente_enviado_at = new Date().toISOString();
}

if (previous.evento_tipo === "RESPONSAVEL_1H") {
  body.lembrete_1h_responsavel_enviado = true;
  body.lembrete_1h_responsavel_enviado_at = new Date().toISOString();
}

if (previous.evento_tipo === "RESPONSAVEL_30MIN") {
  body.lembrete_30min_responsavel_enviado = true;
  body.lembrete_30min_responsavel_enviado_at = new Date().toISOString();
}

return [{
  json: {
    ...previous,
    supabase_body: body
  }
}];

return [{
  json: {
    ok: true,
    status: "sem_lembretes_para_enviar",
    checked_at: new Date().toISOString()
  }
}];
